import { useCallback, useEffect, useRef, useState } from 'react';

import { useDateTimeRangeErrorMessage } from './useDateTimeRangeErrorMessage.js';
import { _useId } from '../../../core/hooks/useId.js';
import type { TimeValue } from '../../../core/types/time.js';
import { useFormFieldMessagesContext } from '../../forms-core/hooks/useFormFieldMessagesContext.js';
import { FormFieldMessagesAction } from '../../forms-core/state/formfield-messages-state-reducer.js';
import { _parseTime } from '../../forms-core/time/timeParser.js';
import type { DateTimeRangeError, DateTimeRangePickerProps } from '../types.js';

export const useDateTimeRangePickerValidation = (
  touchedRef: React.RefObject<HTMLElement>,
  valueFrom: TimeValue | null,
  valueTo: TimeValue | null,
  validationProps: Pick<DateTimeRangePickerProps, 'max' | 'min' | 'precision'>,
) => {
  const [error, setError] = useState<DateTimeRangeError>(null);
  const [errorFrom, setErrorFrom] = useState<DateTimeRangeError>(null);
  const [errorTo, setErrorTo] = useState<DateTimeRangeError>(null);

  const { dispatch: dispatchErrorMessage } = useFormFieldMessagesContext();
  const { getErrorMessage } = useDateTimeRangeErrorMessage(validationProps);

  // use shared now value for all expression parsing
  const sharedNow = useRef<number>(Date.now());
  const touched = useRef(false);

  const dateTimeRangePickerCustomErrorRef = useRef<string>(
    _useId({ prefix: 'strato-datetimerange-error' }),
  );

  // Create a timevalue baed on current expression
  const evaluate = useCallback(
    (input: string | null) => _parseTime(input, sharedNow.current),
    [],
  );

  // Update the timestamp for expression base timevalue instances
  const reevaluate = useCallback(
    (value: TimeValue | null) => {
      if (value?.type === 'expression') {
        return evaluate(value.value);
      }

      return value;
    },
    [evaluate],
  );

  const validate = useCallback(
    (from: TimeValue | null, to: TimeValue | null) => {
      // don't validate anything if not touched
      if (!touched.current) {
        return;
      }

      const newError = errorFrom || errorTo || null;

      // if only one of the values is provided, both need to be present, otherwise it's still an invalid state
      if (!newError && ((from && !to) || (to && !from))) {
        setError('valueMissing');
        return;
      }

      // if the from value is the same or bigger than the to value, it's an invalid order error
      if (
        from &&
        to &&
        new Date(from.absoluteDate).getTime() >=
          new Date(to.absoluteDate).getTime()
      ) {
        setError('invalidOrder');
        return;
      }

      setError(newError);
    },
    [errorFrom, errorTo],
  );

  // set the component to touched, if the touchedRef container is loosing the focus
  const onBlurTouched: React.FocusEventHandler = useCallback(
    (e) => {
      if (!touched.current && !touchedRef.current?.contains(e.relatedTarget)) {
        touched.current = true;
      }

      validate(valueFrom, valueTo);
    },
    // no need to set the touched refs as dep.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [validate, valueFrom, valueTo],
  );

  // error validation effect
  useEffect(() => {
    validate(valueFrom, valueTo);
  }, [validate, valueFrom, valueTo]);

  // promote error state
  useEffect(() => {
    // don't validate anything if not touched
    if (!touched.current) {
      return;
    }

    // check the source of the error
    const source =
      error === errorFrom && errorFrom === errorTo
        ? 'both'
        : errorTo === error
        ? 'to'
        : 'from';

    // clear error upfront .. seems wrong :)
    dispatchErrorMessage({
      type: FormFieldMessagesAction.REMOVEMESSAGE,
      payload: {
        id: dateTimeRangePickerCustomErrorRef.current,
        messageType: 'formcontrol',
      },
    });

    error &&
      dispatchErrorMessage({
        type: FormFieldMessagesAction.ADDMESSAGE,
        payload: {
          id: dateTimeRangePickerCustomErrorRef.current,
          validityStateKey: 'customError',
          variant: 'error',
          message: getErrorMessage(error, source),
          messageType: 'formcontrol',
        },
      });
  }, [dispatchErrorMessage, error, errorFrom, errorTo, getErrorMessage]);

  return {
    evaluate,
    reevaluate,
    onBlurTouched,
    onError: {
      from: setErrorFrom,
      to: setErrorTo,
    },
    error,
  };
};
